#include <item/ForgeRuntime.hpp>
#include <algorithm>
#include <map>
#include <set>
namespace auriga::item {
namespace {
using E=ItemPersistenceError;
struct Decision {std::uint64_t target=0,scroll=0;std::array<std::uint64_t,3> boosters{};std::uint32_t recipe=0;std::uint16_t roll=0;ForgeContext context;std::uint64_t walletRevision=0,gold=0;ForgeTerms terms;bool success=false;};
void Put(std::vector<std::uint8_t>& b,std::uint64_t v,unsigned n){for(unsigned j=0;j<n;++j)b.push_back(static_cast<std::uint8_t>(v>>(j*8)));}
std::uint64_t Get(std::span<const std::uint8_t> b,unsigned at,unsigned n){std::uint64_t v=0;for(unsigned j=0;j<n;++j)v|=std::uint64_t{b[at+j]}<<(j*8);return v;}
std::vector<std::uint8_t> Encode(const Decision& d){std::vector<std::uint8_t> b{'F','G','R',1};Put(b,d.target,8);Put(b,d.scroll,8);for(auto id:d.boosters)Put(b,id,8);Put(b,d.recipe,4);Put(b,d.roll,2);Put(b,d.context.actor.level,2);Put(b,d.context.actor.characterClass,1);Put(b,d.context.actor.sex,1);Put(b,d.context.actor.inCombat,1);Put(b,d.context.admitted,1);Put(b,d.context.alive,1);Put(b,d.context.npcInRange,1);Put(b,d.walletRevision,8);Put(b,d.gold,8);Put(b,d.terms.chanceBp,2);Put(b,unsigned(d.terms.failure),1);Put(b,d.terms.failureLevel,2);Put(b,d.terms.targetLevel,2);Put(b,d.success,1);return b;}
std::optional<Decision> Read(std::span<const std::uint8_t> b){if(b.size()!=82 || b[0]!='F' || b[1]!='G' || b[2]!='R' || b[3]!=1 || b[54]>1 || b[55]>1 || b[56]>1 || b[57]>1 || b[81]>1)return {};Decision d;d.target=Get(b,4,8);d.scroll=Get(b,12,8);for(unsigned j=0;j<3;++j)d.boosters[j]=Get(b,20+j*8,8);d.recipe=Get(b,44,4);d.roll=Get(b,48,2);d.context.actor={static_cast<std::uint16_t>(Get(b,50,2)),b[52],b[53]};d.context.actor.inCombat=b[54];d.context.admitted=b[55];d.context.alive=b[56];d.context.npcInRange=b[57];d.walletRevision=Get(b,58,8);d.gold=Get(b,66,8);d.terms={static_cast<std::uint16_t>(Get(b,74,2)),static_cast<RefinementFailure>(b[76]),static_cast<std::uint16_t>(Get(b,77,2)),static_cast<std::uint16_t>(Get(b,79,2)),0};d.success=b[81];return d;}
unsigned TargetMask(const ItemCatalogEntry& e){if(std::holds_alternative<ItemWeaponRow>(e.category))return 1;if(std::holds_alternative<ItemArmorRow>(e.category))return 2;if(std::holds_alternative<ItemAccessoryRow>(e.category))return 4;const auto* s=std::get_if<ItemSocketStoneRow>(&e.category);return s && s->kind==SocketStoneKind::Insertable?8:0;}
const PersistentItem* Find(std::span<const PersistentItem> all,std::uint64_t id){const auto i=std::ranges::find(all,id,[](const auto& p){return p.id.Value();});return i==all.end()?nullptr:&*i;}
struct Prepared {RefinementRecipe recipe;const PersistentItem* target=nullptr;std::map<std::uint64_t,std::uint32_t> aids;};
std::expected<Prepared,E> Prepare(const ItemCatalog& c,ItemOwner owner,std::span<const PersistentItem> all,const Decision& d){
    if(!d.context.admitted || !d.context.alive || d.context.actor.characterClass>3 || d.context.actor.sex>1 || owner.kind!=ItemOwnerKind::Character)return std::unexpected(E::RequirementNotMet);
    const auto* target=Find(all,d.target);const auto* recipe=c.FindRefinementRecipe(d.recipe);
    if(!target || !recipe || !ValidatePersistentItem(c,*target) || target->destroyed || target->owner!=owner || !target->placement || target->placement->kind!=ItemStorageKind::Inventory || target->count!=1 || target->attributes.lockedSlot || !TargetMask(*c.Find(target->key)))return std::unexpected(E::InvalidItem);
    if(target->key!=recipe->source || target->refinementLevel!=recipe->sourceLevel)return std::unexpected(E::InvalidLevel);
    if(!d.scroll && (!d.context.npcInRange || std::ranges::none_of(d.boosters,[](auto id){return id!=0;})))return std::unexpected(E::RequirementNotMet);
    Prepared p{*recipe,target,{}};std::uint32_t bonus=0;std::set<std::uint64_t> ids{d.target};
    const auto aid=[&](std::uint64_t id,ForgeAidKind kind,unsigned group)->std::expected<const ItemForgeAidRow*,E>{
        if(!ids.insert(id).second)return std::unexpected(E::InvalidChange);const auto* item=Find(all,id);if(!item || !PlainInventoryItem(*item,owner) || !ValidatePersistentItem(c,*item))return std::unexpected(E::InvalidItem);const auto* entry=c.Find(item->key);const auto* r=std::get_if<ItemForgeAidRow>(&entry->category);const auto* use=c.FindUsePolicy(entry->base.usePolicy);
        if(!r || entry->base.retired || r->kind!=kind || r->boosterGroup!=group || item->count<r->units || target->refinementLevel<r->minimumLevel || target->refinementLevel>r->maximumLevel || !(r->targetMask&TargetMask(*c.Find(target->key))) || entry->base.minimumLevel>d.context.actor.level || !use || !(use->allowedClasses>>d.context.actor.characterClass&1) || !(use->allowedSexes>>d.context.actor.sex&1) || (d.context.actor.inCombat && !use->useDuringCombat))return std::unexpected(E::RequirementNotMet);
        p.aids[id]=r->units;return r;
    };
    if(d.scroll){auto found=aid(d.scroll,ForgeAidKind::Scroll,0);if(!found)return std::unexpected(found.error());const auto& r=**found;
        if(r.chanceMode==ForgeChance::Replace)p.recipe.successChanceBp=r.chanceBp;else if(r.chanceMode==ForgeChance::Levels)p.recipe.successChanceBp=r.levels[target->refinementLevel-r.minimumLevel].chanceBp;
        if(r.failure!=ForgeFailure::Recipe){p.recipe.failureLevel.reset();if(r.failure==ForgeFailure::Keep)p.recipe.failure=RefinementFailure::Keep;else if(r.failure==ForgeFailure::Destroy)p.recipe.failure=RefinementFailure::Destroy;else if(target->refinementLevel){p.recipe.failure=RefinementFailure::SetLevel;p.recipe.failureLevel=target->refinementLevel-1;}else p.recipe.failure=RefinementFailure::Keep;}
    }
    for(unsigned j=0;j<3;++j)if(d.boosters[j]){auto r=aid(d.boosters[j],ForgeAidKind::Booster,j+1);if(!r)return std::unexpected(r.error());bonus+=(**r).chanceBp;}
    p.recipe.successChanceBp=static_cast<std::uint16_t>(std::min(10000u,std::uint32_t(p.recipe.successChanceBp)+bonus));
    if(!ValidateRefinementRecipe(p.recipe,c))return std::unexpected(E::InvalidChange);return p;
}
std::expected<ForgeCommit,E> Build(const ItemCatalog& c,std::array<std::uint8_t,16> op,ItemOwnerFence owner,std::span<const ItemStorageLayout> layouts,std::span<const PersistentItem> all,const ItemWallet& wallet,Decision d,bool probe){
    const auto prepared=Prepare(c,owner.owner,all,d);if(!prepared)return std::unexpected(prepared.error());const auto& p=*prepared;
    if(wallet.owner!=owner.owner || wallet.currency!=WalletCurrency::Gold || wallet.revision!=d.walletRevision || wallet.balance!=d.gold)return std::unexpected(E::InvalidWallet);
    if(probe)d.roll=p.recipe.successChanceBp==0 || p.recipe.successChanceBp==10000?0:1;
    std::vector<RefinementItemSnapshot> inventory;std::set<ItemInstanceId> ids;
    for(const auto& i:all){if(!ids.insert(i.id).second)return std::unexpected(E::InvalidItem);if(!i.destroyed && i.owner==owner.owner && i.placement && i.placement->kind==ItemStorageKind::Inventory){if(!ValidatePersistentItem(c,i))return std::unexpected(E::InvalidItem);const bool locked=i.id!=p.target->id && (!PlainInventoryItem(i,owner.owner) || p.aids.contains(i.id.Value()) || i.key.Category()==ItemCategory::ForgeAid);inventory.push_back({i.id.Value(),i.revision,i.owner.id,i.key,i.refinementLevel,i.count,locked});}}
    const auto& source=*p.target;const auto plan=PrepareRefinementRecipe(c,p.recipe,{op,owner.owner.id,wallet.revision,wallet.balance,true},{source.id.Value(),source.revision,source.owner.id,source.key,source.refinementLevel,source.count,false},inventory,d.roll);if(!plan)return std::unexpected(E::RequirementNotMet);
    ItemCommit out;out.operationId=op;out.catalogRevision=c.Revision();out.catalogHash=c.ContentHash();out.kind=ItemOperationKind::Service;out.outcomeCode=ForgeOutcome;out.owners={owner};auto after=source;++after.revision;if(plan->result){after.key=*plan->result;after.refinementLevel=*plan->resultLevel;}else{after.destroyed=true;after.count=0;after.placement.reset();}out.items.push_back({source,after});auto debits=p.aids;for(const auto& debit:plan->debits){if(debits.contains(debit.instanceId))return std::unexpected(E::InvalidChange);debits.emplace(debit.instanceId,debit.consumeCount);}
    for(auto [id,units]:debits){const auto* before=Find(all,id);if(!before || !units || units>before->count)return std::unexpected(E::InvalidChange);auto after=*before;++after.revision;after.count-=units;if(!after.count){after.destroyed=true;after.placement.reset();}out.items.push_back({*before,after});}
    if(plan->goldCost){auto next=wallet;++next.revision;next.balance-=plan->goldCost;out.wallets.push_back({wallet,next});}
    for(const auto& ch:out.items)for(const auto* i:{&*ch.before,&ch.after})if(i->placement){const auto l=std::ranges::find(layouts,ItemStorage{i->owner,i->placement->kind,i->placement->storageId},&ItemStorageLayout::storage);if(l==layouts.end())return std::unexpected(E::InvalidStorage);if(std::ranges::find(out.storages,*l)==out.storages.end())out.storages.push_back(*l);}
    d.terms={p.recipe.successChanceBp,p.recipe.failure,p.recipe.failureLevel.value_or(p.recipe.sourceLevel),p.recipe.targetLevel,p.recipe.goldCost};d.success=plan->success;out.result=Encode(d);return ForgeCommit{std::move(out),d.terms,d.success};
}
bool AccessoryDebit(const ItemChange& ch){if(!ch.before || !ch.before->accessory || !ch.after.accessory || !ch.before->placement || ch.before->placement->kind!=ItemStorageKind::Equipment)return false;const auto& b=*ch.before->accessory;const auto& a=*ch.after.accessory;if(b.permanent || a.permanent || !b.activeGrade || a.unlockedCapacity!=b.unlockedCapacity || a.activeGrade>b.activeGrade || (a.activeGrade==b.activeGrade && a.remainingMs>=b.remainingMs))return false;auto p=*ch.before;p.revision=ch.after.revision;p.accessory=a;return p==ch.after;}
}
std::expected<ForgeCommit,E> MakeForgeCommit(const ItemCatalog& c,std::array<std::uint8_t,16> op,ItemOwnerFence owner,std::span<const ItemStorageLayout> layouts,std::span<const PersistentItem> all,const ItemWallet& wallet,const ForgeSelection& selection,ForgeContext context,std::optional<std::uint16_t> roll){Decision d;d.target=selection.target.Value();d.scroll=selection.scroll;d.boosters=selection.boosters;d.recipe=selection.recipe;d.context=context;d.walletRevision=wallet.revision;d.gold=wallet.balance;d.roll=roll.value_or(0);auto result=Build(c,op,owner,layouts,all,wallet,d,!roll);if(!result)return std::unexpected(result.error());if(const auto valid=ValidateItemCommit(c,result->commit);!valid)return std::unexpected(valid.error());return result;}
bool ValidForgeWrite(const ItemCatalog& c,const ItemCommit& r){if(r.kind!=ItemOperationKind::Service || r.owners.size()!=1 || r.wallets.size()>1 || r.ground || r.recovery || r.learning || r.petStudyCooldown)return false;const auto d=Read(r.result);if(!d)return false;std::vector<PersistentItem> before;for(const auto& ch:r.items){if(!ch.before)return false;before.push_back(*ch.before);}const ItemWallet wallet{r.owners[0].owner,WalletCurrency::Gold,d->walletRevision,d->gold};const auto expected=Build(c,r.operationId,r.owners[0],r.storages,before,wallet,*d,false);if(!expected || expected->commit.result!=r.result || expected->commit.wallets.size()!=r.wallets.size())return false;for(unsigned j=0;j<r.wallets.size();++j)if(r.wallets[j].before!=expected->commit.wallets[j].before || r.wallets[j].after!=expected->commit.wallets[j].after)return false;unsigned matched=0;for(const auto& ch:r.items){const auto i=std::ranges::find(expected->commit.items,ch.after.id,[](const auto& x){return x.after.id;});if(i==expected->commit.items.end()){if(!AccessoryDebit(ch))return false;}else{if(ch.before!=i->before || ch.after!=i->after)return false;++matched;}}return matched==expected->commit.items.size();}
}
